#include "posix_internal.h"

#include <zephyr/init.h>
#include <zephyr/kernel.h>
#include <zephyr/sys/bitarray.h>
#include <zephyr/posix/pthread.h>
#include <zephyr/sys/slist.h>

struct pthread_key_obj {
	/* List of pthread_key_data objects that contain thread
	 * specific data for the key.Wait on this condition variable.
	 */
	sys_slist_t key_data_l;

	/* Optional destructor that is passed to pthread_key_create() */
	void (*destructor)(void *);
};

/* This is crucial to keep track of keys across all threads */
static struct k_spinlock pthread_key_lock;

static struct pthread_key_obj posix_key_pool[CONFIG_POSIX_THREAD_KEYS_MAX];
SYS_BITARRAY_DEFINE_STATIC(posix_key_bitarray, CONFIG_POSIX_THREAD_KEYS_MAX);

static inline size_t posix_key_to_offset(struct pthread_key_obj *k)
{
	return k - posix_key_pool;
}

static inline uint32_t get_posix_key_idx(uint32_t key)
{
	return mark_posix_obj_uninitialized(key);
}

struct pthread_key_obj *get_posix_key(pthread_key_t key)
{
	int actually_initialized;
	size_t bit = get_posix_key_idx(key);

	/* if the provided cond does not claim to be initialized, its invalid */
	if (!is_posix_obj_initialized(key)) {
		return NULL;
	}

	/* Mask off the MSB to get the actual bit index */
	if (sys_bitarray_test_bit(&posix_key_bitarray, bit, &actually_initialized) < 0) {
		return NULL;
	}

	if (actually_initialized == 0) {
		/* The key claims to be initialized, but is actually not */
		return NULL;
	}

	return (struct pthread_key_obj *)&posix_key_pool[bit];
}

/**
 * @brief Create a key for thread-specific data
 *
 * See IEEE 1003.1
 */
int pthread_key_create(pthread_key_t *key, void (*destructor)(void *))
{
	size_t bit;
	int ret = ENOMEM;
	struct pthread_key_obj *new_key;

	/* Acquire a key */
	if (sys_bitarray_alloc(&posix_key_bitarray, 1, &bit) < 0) {
		return ENOMEM;
	}

	new_key = &posix_key_pool[bit];
	(void)memset(new_key, 0, sizeof(*new_key));

	K_SPINLOCK(&pthread_key_lock) {
		sys_slist_init(&(new_key->key_data_l));

		new_key->destructor = destructor;
		*key = mark_posix_obj_initialized(bit);
		ret = 0;
	}

	return ret;
}

/**
 * @brief Delete a key for thread-specific data
 *
 * See IEEE 1003.1
 */
int pthread_key_delete(pthread_key_t key)
{
	size_t bit;
	int ret = EINVAL;
	struct pthread_key_obj *key_obj;
	struct pthread_key_data *key_data;
	sys_snode_t *node_l, *next_node_l;
	k_spinlock_key_t key_key;

	key_key = k_spin_lock(&pthread_key_lock);

	key_obj = get_posix_key(key);
	if (key_obj == NULL) {
		k_spin_unlock(&pthread_key_lock, key_key);
		return EINVAL;
	}

	/* Delete thread-specific elements associated with the key */
	SYS_SLIST_FOR_EACH_NODE_SAFE(&(key_obj->key_data_l), node_l, next_node_l) {

		/* Remove the object from the list key_data_l */
		key_data = (struct pthread_key_data *)sys_slist_get(&(key_obj->key_data_l));

		/* Deallocate the object's memory */
		k_spin_unlock(&pthread_key_lock, key_key);
		k_free((void *)key_data);
		key_key = k_spin_lock(&pthread_key_lock);
	}

	bit = posix_key_to_offset(key_obj);
	ret = sys_bitarray_free(&posix_key_bitarray, 1, bit);
	__ASSERT_NO_MSG(ret == 0);

	k_spin_unlock(&pthread_key_lock, key_key);

	return 0;
}

/**
 * @brief Associate a thread-specific value with a key
 *
 * See IEEE 1003.1
 */
int pthread_setspecific(pthread_key_t key, const void *value)
{
	struct pthread_key_obj *key_obj;
	struct posix_thread *thread = to_posix_thread(pthread_self());
	struct pthread_key_data *key_data;
	pthread_thread_data *thread_spec_data;
	k_spinlock_key_t key_key;
	sys_snode_t *node_l;
	int retval = 0;

	if (thread == NULL) {
		return EINVAL;
	}

	/* Traverse the list of keys set by the thread, looking for key.
	 * If the key is already in the list, re-assign its value.
	 * Else add the key to the thread's list.
	 */
	key_key = k_spin_lock(&pthread_key_lock);

	key_obj = get_posix_key(key);
	if (key_obj == NULL) {
		k_spin_unlock(&pthread_key_lock, key_key);
		return EINVAL;
	}

	SYS_SLIST_FOR_EACH_NODE(&(thread->key_list), node_l) {

		thread_spec_data = (pthread_thread_data *)node_l;

		if (thread_spec_data->key == key_obj) {

			/* Key is already present so
			 * associate the value with the key
			 */
			thread_spec_data->data = (void *)value;
			goto out;
		}
	}

	if (node_l == NULL) {
		k_spin_unlock(&pthread_key_lock, key_key);

		/* Allocate memory for new key data, Re-acquire spinlock */
		key_data = k_malloc(sizeof(struct pthread_key_data));
		key_key = k_spin_lock(&pthread_key_lock);

		if (key_data == NULL) {
			retval = ENOMEM;
			goto out;
		} else {
			/* Associate thread specific data, initialize new key */
			key_data->thread_data.key = key_obj;
			key_data->thread_data.data = (void *)value;

			/* Append new key data to thread's key list */
			sys_slist_append((&thread->key_list),
					 (sys_snode_t *)(&key_data->thread_data));

			/* Append new key data to the key object's list */
			sys_slist_append(&(key_obj->key_data_l), (sys_snode_t *)key_data);
		}
	}

out:
	k_spin_unlock(&pthread_key_lock, key_key);

	return retval;
}

/**
 * @brief Get the thread-specific value associated with the key
 *
 * See IEEE 1003.1
 */
void *pthread_getspecific(pthread_key_t key)
{
	struct pthread_key_obj *key_obj;
	struct posix_thread *thread = to_posix_thread(pthread_self());
	pthread_thread_data *thread_spec_data;
	void *value = NULL;
	sys_snode_t *node_l;

	if (thread == NULL) {
		return NULL;
	}

	K_SPINLOCK(&pthread_key_lock) {
		key_obj = get_posix_key(key);
		if (key_obj == NULL) {
			K_SPINLOCK_BREAK;
		}

		node_l = sys_slist_peek_head(&(thread->key_list));

		/* Traverse the list of keys set by the thread, looking for key */
		SYS_SLIST_FOR_EACH_NODE(&(thread->key_list), node_l) {
			thread_spec_data = (pthread_thread_data *)node_l;
			if (thread_spec_data->key == key_obj) {
				/* Key is present, so get the set thread data */
				value = thread_spec_data->data;
				break;
			}
		}
	}

	return value;
}

void pthread_key_ator_teardown(struct posix_thread *pt)
{
	void *val;
	sys_snode_t *node_l, *next_node_l;
	struct pthread_key_obj *key_obj;
	struct pthread_key_data *key_data;
	pthread_thread_data *thread_spec_data;
	k_spinlock_key_t key;

	/* Perform destructor callbacks Before deallocating memory */
	SYS_SLIST_FOR_EACH_NODE_SAFE(&(pt->key_list), node_l, next_node_l) {
		thread_spec_data = (pthread_thread_data *)node_l;
		key_obj = thread_spec_data->key;
		if (key_obj->destructor != NULL) {
			val = thread_spec_data->data;
			thread_spec_data->data = NULL;
			(key_obj->destructor)(val);
		}
	}

	key = k_spin_lock(&pthread_key_lock);
	SYS_SLIST_FOR_EACH_NODE_SAFE(&(pt->key_list), node_l, next_node_l) {
		thread_spec_data = (pthread_thread_data *)sys_slist_get(&(pt->key_list));
		key_obj = thread_spec_data->key;
		key_data = CONTAINER_OF(thread_spec_data, struct pthread_key_data, thread_data);
		sys_slist_find_and_remove(&(key_obj->key_data_l), (sys_snode_t *)key_data);
		k_spin_unlock(&pthread_key_lock, key);
		k_free((void *)key_data);
		key = k_spin_lock(&pthread_key_lock);
	}
	k_spin_unlock(&pthread_key_lock, key);
}
